"""Mutalia-e-Quran XII PDF48: p.45 — verses 4:145 (begun on p.44)–152 (4:153 begins at the foot; recorded on p.46). Run: python class12_quran_page048.py"""
from class12_quran_common import BOOK, Builder, rec, V


def p48():
    b = Builder()
    V(b, 4, 145, 'بے شک منافقین جہنم کے سب سے نچلے طبقہ میں ہوں گے اور تم اُن کے لیے ہرگز کوئی مدد گار نہ پاؤ گے۔',
      'بې‌شکه منافقان به د دوزخ په تر ټولو ښکته طبقه کې وي، او هېڅکله به ورته کوم مرستندوی ونه مومئ.')
    V(b, 4, 146, 'سوائے اُن لوگوں کے جنھوں نے توبہ کی اور (اپنی) اصلاح کر لی اور اللہ (کے سہارے) کو مضبوطی سے تھام لیا اور اپنے دین کو اللہ کے لیے خالص کر لیا تو ایسے لوگ مومنوں کے ساتھ ہیں اور عنقریب اللہ مومنوں کو اجرِ عظیم عطا فرمائے گا۔',
      'پرته له هغو کسانو چې توبه یې وکړه، (ځانونه یې) سم کړل، د الله (پر ملاتړ) یې په کلکه منګولې ولګولې او خپل دین یې الله ته خالص کړ؛ نو داسې خلک له مؤمنانو سره دي، او ژر به الله مؤمنانو ته لوی اجر ورکړي.')
    V(b, 4, 147, 'اللہ تمھیں عذاب دے کر کیا کرے گا اگر تم شکر ادا کرو اور ایمان لے آؤ اور اللہ بڑا قدردان خوب جاننے والا ہے۔',
      'الله به تاسو په عذاب څه وکړي که شکر ادا کړئ او ایمان راوړئ؟ او الله ډېر قدردان، ښه پوه دی.')
    V(b, 4, 148, 'اللہ اس بات کو پسند نہیں کرتا کہ (کسی کی) کوئی بُری بات علانیہ کہی جائے سوائے اُس کے کہ جس پر ظلم کیا گیا اور اللہ خوب سننے والا خوب جاننے والا ہے۔',
      'الله دا نه خوښوي چې د (چا) کومه بده خبره په ښکاره وویل شي، پرته له هغه چا چې ظلم پرې شوی؛ او الله ښه اورېدونکی، ښه پوه دی.')
    V(b, 4, 149, 'اگر تم کوئی بھلائی علانیہ کرو یا اُسے پوشیدہ رکھو یا (کسی کی) برائی کو معاف کر دو تو بے شک اللہ بہت معاف فرمانے والا خوب قدرت رکھنے والا ہے۔',
      'که کومه ښېګڼه په ښکاره وکړئ یا یې پټه وساتئ یا د (چا) بدي وبښئ، نو بې‌شکه الله ډېر معاف کوونکی، ښه قدرت لرونکی دی.')
    V(b, 4, 150, 'بے شک جو لوگ اللہ اور اُس کے رسولوں کا انکار کرتے ہیں اور چاہتے ہیں کہ اللہ اور اُس کے رسولوں کے درمیان فرق کریں اور وہ کہتے ہیں کہ ہم بعض (رسولوں) پر ایمان لائیں گے اور بعض کا انکار کریں گے اور چاہتے ہیں کہ اس طرح (ایمان و کفر) کے درمیان کوئی راہ نکال لیں۔',
      'بې‌شکه هغه کسان چې له الله او د هغه له رسولانو انکار کوي، غواړي چې د الله او د هغه د رسولانو ترمنځ توپیر وکړي، او وایي: «پر ځینو (رسولانو) به ایمان راوړو او له ځینو به انکار کوو»، او غواړي چې په دې ډول د (ایمان او کفر) ترمنځ کومه لاره وباسي.')
    V(b, 4, 151, 'یہی لوگ پکے کافر ہیں اور ہم نے کافروں کے لیے ذلت آمیز عذاب تیار کر رکھا ہے۔',
      'همدا خلک پاخه کافران دي، او موږ کافرانو ته سپکوونکی عذاب چمتو کړی.')
    V(b, 4, 152, 'اور جو لوگ اللہ اور اُس کے رسولوں پر ایمان لائے اور ان میں سے کسی ایک کے درمیان بھی فرق نہیں کیا یہ وہ لوگ ہیں جنھیں اللہ ان کے اجر جلد عطا فرمائے گا اور اللہ بڑا ہی بخشنے والا نہایت رحم فرمانے والا ہے۔',
      'او هغه کسان چې پر الله او د هغه پر رسولانو یې ایمان راوړ او د هغوی د یوه ترمنځ یې هم توپیر ونه کړ، دا هغه خلک دي چې الله به یې ژر اجرونه ورکړي؛ او الله ډېر بښونکی، بې‌حده مهربان دی.')
    BOOK.save(48, [(5, rec(b, 5, 48, 48))], issues=[{'id': 'mq12-pdf048', 'unit': 5, 'printedPage': 45,
               'description': 'Verse 4:145 (begun on p.44) recorded here; 4:153 begins on the last lines of p.45 and is recorded with p.46. Ruku sign after verse 152 not reproduced.'}])


if __name__ == '__main__':
    p48()
